import random
import string

def generate_random_word(length):
    """Generate a random word of the given length."""
    return ''.join(random.choices(string.ascii_lowercase, k=length))

def suggest_letters(word, guessed_letters):
    """Suggest letters that can be used to complete the word."""
    suggestions = set()
    for i in range(len(word)):
        for letter in string.ascii_lowercase:
            if letter not in guessed_letters and word[i] + letter in word:
                suggestions.add(letter)
    return suggestions

def play_hangman(word):
    """Play the hangman game with the given word."""
    guessed_letters = set()
    word_length = len(word)
    guessed_word = '_' * word_length

    while '_' in guessed_word:
        print(guessed_word)
        letter = input("Guess a letter: ").lower()
        if letter in guessed_letters:
            print("You've already guessed that letter.")
        elif len(letter) != 1:
            print("Please enter a single letter.")
        else:
            guessed_letters.add(letter)
            suggestions = suggest_letters(word, guessed_letters)
            if suggestions:
                print(f"The following letters can be used: {', '.join(suggestions)}")
            else:
                print("You've guessed the word correctly!")
                break

    if '_' not in guessed_word:
        print("Congratulations! You've won the game.")

# Generate a random word and play the game
word = generate_random_word(6)
play_hangman(word)
